  px[a]=d.close
P=pd.DataFrame(px); R=P.pct_change();
# Cross-asset dispersion of the completed prior session, threshold based only on earlier sessions.
disp=R.std(axis=1,min_periods=8); threshold=disp.rolling(60,min_periods=40).quantile(.70).shift(1)
active=(disp>threshold).shift(1).fillna(False)
# At date t use returns through t-1, cross-sectional demeaned and volatility scaled.
lag=R.shift(1); vol=R.rolling(20,min_periods=15).std().shift(1)
