fr={h:p.shift(-h).div(p)-1 for h in [1,5,10]}
print('period',p.index.min().date(),p.index.max().date(),'assets',len(A))
for h,x in fr.items():
 vals=[];ns=[];ds=[]
 for dt in f.index:
  z=pd.concat([f.loc[dt],x.loc[dt]],axis=1).dropna()
  if len(z)>=8:
   vals.append(spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic); ns.append(len(z)); ds.append(dt)
 s=pd.Series(vals,index=ds).dropna(); print('horizon',h,'valid_dates',len(s),'avg_n',round(np.mean(ns),2),'IC',round(s.mean(),5),'ICIR',round(s.mean()/s.std(ddof=1)*np.sqrt(len(s)),5),'hit',round((s>0).mean(),4))
