import numpy as np,pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data,get_index_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
def f(s):
 d=get_stock_daily_data(s,4000)
 if d is None or len(d)<100:d=get_index_daily_data(s,4000)
 return d
c=pd.DataFrame({s:f(s).set_index('date').close for s in U}).sort_index(); r=c.pct_change(); sig=-r.rolling(6,min_periods=6).sum().shift(1)
for h in [1,5,10]:
 z=[]
 for dt in sig.index:
  x=pd.concat([sig.loc[dt],c.pct_change(h).shift(-h).loc[dt]],axis=1).dropna()
  if len(x)>=8:z.append((dt,x.iloc[:,0].corr(x.iloc[:,1]),len(x)))
 z=pd.DataFrame(z,columns=['date','ic','n']).set_index('date'); m=z.ic.mean();sd=z.ic.std(ddof=1)
 print(f'H={h} dates={len(z)} avgN={z.n.mean():.2f} IC={m:.8f} ICIR={m/sd*np.sqrt(len(z)):.8f} hit={(z.ic>0).mean():.4f}')
 if h==1:
  for a,b in [('2020','2022'),('2023','2025'),('2026','2027'),('2028','2028')]:
   q=z.loc[a:b]
   if len(q):print(f'regime {a}-{b} dates={len(q)} IC={q.ic.mean():.8f}')
print('coverage',sig.notna().sum(axis=1).mean()/15,'turnover',sig.rank(axis=1,pct=True).diff().abs().mean(axis=1).mean(),'instruments',c.shape[1])

import numpy as np
import pandas as pd
from alphacrafter.sim.utils import get_account_dict, get_index_daily_data, get_stock_daily_data

U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
def fetch(s):
    d=get_index_daily_data(s, days=4000)
    if d is None: d=get_stock_daily_data(s, days=4000)
    return d

# interpretable range-expansion continuation: 5d signed return multiplied by capped
# current 3d average high-low range relative to 30d median range.
series={}
for s in U:
    d=fetch(s)
    if d is None or len(d)<100: continue
    d=d.copy(); d['date']=pd.to_datetime(d['date']); d=d.set_index('date').sort_index()
    r=d['close'].pct_change(); rng=(d['high']-d['low'])/d['close']
    expansion=(rng.rolling(3).mean()/rng.rolling(30).median()).clip(0.5,2.0)
    sig=r.rolling(5).sum()*expansion
    series[s]=pd.DataFrame({'sig':sig,'fwd1':d['close'].pct_change().shift(-1),'fwd5':d['close'].shift(-5)/d['close']-1,'fwd10':d['close'].shift(-10)/d['close']-1})

def eval(h):
    rows=[]
    for dt in sorted(set().union(*[x.index for x in series.values()])):
        a=[]
        for s,x in series.items():
            if dt in x.index and np.isfinite(x.loc[dt,'sig']) and np.isfinite(x.loc[dt,h]): a.append((x.loc[dt,'sig'],x.loc[dt,h],s))
        if len(a)>=8:
            z=pd.DataFrame(a,columns=['sig','ret','s']); ic=z.sig.rank().corr(z.ret.rank())
            rows.append((dt,ic,len(a),z.sig.rank().corr(z.ret.rank())))
    q=pd.DataFrame(rows,columns=['date','ic','n','x'])
    mean=q.ic.mean(); sd=q.ic.std(ddof=1); icir=mean/sd*np.sqrt(252) if sd else np.nan
    # rank turnover on consecutive common dates
    turns=[]; prev=None
    for dt in q.date:
        ranks={s: i for i,s in enumerate(sorted([s for s,x in series.items() if dt in x.index and np.isfinite(x.loc[dt,'sig'])], key=lambda s:series[s].loc[dt,'sig']))}
        if prev is not None:
            common=set(prev)&set(ranks)
