from alphacrafter.sim.utils import get_index_daily_data,get_stock_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
def fetch(s):
 for f in (get_index_daily_data,get_stock_daily_data):
  try:
   d=f(s,days=4000)
   if d is not None and len(d): return d
  except Exception: pass
S={}
for s in U:
 d=fetch(s)
 if d is None: continue
 d=d.copy(); d.date=pd.to_datetime(d.date); d=d.set_index('date').sort_index(); c=pd.to_numeric(d.close,errors='coerce'); r=c.pct_change()
 # Trend persistence: medium return weighted by fraction of positive sessions.
 S[s]=pd.DataFrame({'r40':c.pct_change(40),'persist':(r>0).rolling(20,min_periods=15).mean(),'f1':c.shift(-1)/c-1,'f5':c.shift(-5)/c-1,'f10':c.shift(-10)/c-1})
D=sorted(set().union(*[x.index for x in S.values()])); rows=[]
for dt in D:
 a=[]
 for s,x in S.items():
  if dt in x.index and np.isfinite(x.loc[dt]).all(): a.append((s,*x.loc[dt].values))
 if len(a)>=8:
  z=pd.DataFrame(a,columns=['s','r40','persist','f1','f5','f10']); z['sig']=z.r40*(0.5+z.persist)
  for h in [1,5,10]:
