import numpy as np
import pandas as pd
from alphacrafter.sim.utils import get_index_daily_data
UNIVERSE=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
series={}
for s in UNIVERSE:
 d=get_index_daily_data(s,days=3000)
 if d is not None and len(d)>100:
  d=d.copy(); d['date']=pd.to_datetime(d['date']); series[s]=d.set_index('date')['close'].astype(float).sort_index()
prices=pd.concat(series,axis=1).sort_index(); ret=prices.pct_change()
fac=-(prices.pct_change(5))/(ret.rolling(20).std()*np.sqrt(252))
def validate(h):
 vals=[]; ns=[]
 for dt in fac.index:
  z=pd.concat([fac.loc[dt],prices.shift(-h).loc[dt]/prices.loc[dt]-1],axis=1).dropna()
  if len(z)>=8:
   vals.append(z.iloc[:,0].corr(z.iloc[:,1],method='spearman')); ns.append(len(z))
 return pd.Series(vals).dropna(),ns
ics,ns=validate(10); rank=fac.rank(axis=1,pct=True)
print('factor=-(R5)/(vol20*sqrt252), horizon=10')
print('dates',len(ics),'avg_n',round(float(np.mean(ns)),3),'coverage',round(float(np.mean(ns))/15,5))
print('IC',round(float(ics.mean()),8),'ICIR',round(float(ics.mean()/ics.std(ddof=1)*np.sqrt(len(ics)),5),'hit',round(float((ics>0).mean()),5),'turnover',round(float(rank.diff().abs().mean(axis=1).dropna().mean()),6))
for h in [5,10,20]:
 v,n=validate(h); print('decay',h,round(float(v.mean()),8),len(v))
for y in [2026,2027,2028,2029,2030]:
 v=[]
 for dt in fac.index:
