import pandas as pd, numpy as np
from scipy.stats import spearmanr
CUT=pd.Timestamp('2032-04-14')
assets=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
P=pd.DataFrame({a:pd.read_csv('../persistent/stock_data/'+a+'.csv',parse_dates=['date']).set_index('date')['close'].sort_index() for a in assets}).sort_index()
P=P[P.index<=CUT]; r=P.pct_change(); vix=pd.read_csv('../persistent/index_data/VIX.csv',parse_dates=['date']).set_index('date')['close'].sort_index().reindex(P.index).ffill()
ret20=P/P.shift(20)-1
down=r.where(r<0).rolling(20,min_periods=15).std()*np.sqrt(20)
stress=(vix/vix.rolling(60,min_periods=40).median()).clip(0.5,2.0)
f=ret20.div(down).mul(stress,axis=0)
def calc(h):
 vals=[]; cov=[]; turns=[]
 for i in range(len(P)-h):
  z=pd.concat([f.iloc[i],P.iloc[i+h]/P.iloc[i]-1],axis=1).dropna()
  if len(z)>=8: vals.append(spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic);cov.append(len(z)/15)
 for i in range(1,len(f)):
  z=pd.concat([f.iloc[i-1],f.iloc[i]],axis=1).dropna();
  if len(z): turns.append(np.mean(abs(z.iloc[:,1].rank(pct=True)-z.iloc[:,0].rank(pct=True))))
 a=np.array(vals);return len(a),np.mean(a),np.mean(a)/np.std(a,ddof=1),np.mean(a>0),np.mean(cov),np.mean(turns)
print('cutoff',CUT.date(),'dates',len(P),'assets',P.shape[1])
for h in [5,10,20]:print(h,calc(h))
for start,end in [('2026','2026'),('2027','2027'),('2028','2028'),('2029','2029'),('2030','2030'),('2031','2031'),('2032','2032')]:
 vals=[]
 for i in range(len(P)-20):
  if str(P.index[i].year)!=start:continue
  z=pd.concat([f.iloc[i],P.iloc[i+20]/P.iloc[i]-1],axis=1).dropna()
  if len(z)>=8:vals.append(spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic)
 print('regime',start,len(vals),round(np.mean(vals),5) if vals else None)

