import numpy as np, pandas as pd
from alphacrafter.sim.utils import get_index_daily_data

U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
D={s:get_index_daily_data(s, days=5000) for s in U}
px={s:d.set_index('date')['close'].astype(float).sort_index() for s,d in D.items() if d is not None and len(d)>100}
# factor: reverse of 10d return divided by 20d downside deviation; higher means prefer weak recent performers with resilient downside risk
rows=[]
for dt in sorted(set().union(*[set(x.index) for x in px.values()])):
    vals={}; fw={}
    for s,p in px.items():
        q=p.loc[:dt]
        if len(q)<25: continue
        r=q.pct_change()
        if len(q)<11: continue
        ret=q.iloc[-1]/q.iloc[-11]-1
        dn=r.tail(20).clip(upper=0).std(ddof=1)
        if np.isfinite(dn) and dn>1e-8 and len(p.loc[p.index>dt])>=10:
            vals[s]=-ret/dn
            fw[s]=p.loc[p.index>dt].iloc[9]/q.iloc[-1]-1
    if len(vals)>=8:
        a=pd.Series(vals); b=pd.Series(fw)
        z=pd.concat([a,b],axis=1).dropna()
        if len(z)>=8:
            rows.append((dt,len(z),z.iloc[:,0].corr(z.iloc[:,1],method='spearman')))
x=pd.DataFrame(rows,columns=['date','n','ic']).dropna()
# date-aware turnover of rank ordering
turn=[]; prev=None
for dt in x.date:
    vals=[]
    for s,p in px.items():
        q=p.loc[:dt]; r=q.pct_change()
        if len(q)>=25:
            dn=r.tail(20).clip(upper=0).std(ddof=1)
            if dn>1e-8: vals.append((s,-q.iloc[-1]/q.iloc[-11]/dn+1/dn))
    if len(vals)>=8:
        rank=pd.Series(dict(vals)).rank(pct=True)
        if prev is not None: turn.append(np.mean(abs(rank-prev)))
