import numpy as np, pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data, get_index_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
def get(s,n=4000):
 d=get_stock_daily_data(s,n)
 if d is None or len(d)<100: d=get_index_daily_data(s,n)
 return d
px={s:get(s) for s in U}; rows=[]
# Relative consistency momentum: asset trend relative to the contemporaneous universe median,
# multiplied by directional breadth, then lagged one bar implicitly by using bar i as signal.
for s,d in px.items():
 if d is None: continue
 d=d.sort_values('date').copy(); d['r']=d.close.pct_change()
 d['ret20']=d.close.pct_change(20)
 d['breadth']=(d.r>0).rolling(20).mean()*2-1
 d['raw']=d.ret20*d.breadth
for i in range(40, min(len(d) for d in px.values() if d is not None)-10):
 pass
allr=[]
for s,d in px.items():
 if d is not None:
  allr.append(d.set_index('date')['ret20'].rename(s))
rel=pd.concat(allr,axis=1)
median=rel.median(axis=1)
for s,d in px.items():
 if d is None: continue
 d=d.set_index('date')
 f=(d['ret20']-median)*(d['breadth'])
 for dt in d.index[40:]:
  if dt not in rel.index: continue
  loc=d.index.get_loc(dt)
  if loc+10>=len(d): continue
  fw=d.close.iloc[loc+10]/d.close.iloc[loc]-1
  rows.append((dt,s,f.loc[dt],fw))
x=pd.DataFrame(rows,columns=['date','symbol','factor','fwd']).replace([np.inf,-np.inf],np.nan).dropna()
def stats(z):
 q=[]
 for _,g in z.groupby('date'):
  if len(g)>=8: q.append(g.factor.corr(g.fwd,method='spearman'))
 q=pd.Series(q).dropna()
 return len(q),z.groupby('date').size().mean(),q.mean(),q.mean()/q.std(ddof=1),float((q>0).mean()),z.symbol.nunique()
print('dates',x.date.min(),x.date.max(),'rows',len(x)); print('overall',stats(x))
for a,b in [('2020','2022'),('2023','2024'),('2025','2026'),('2027','2029'),('2030','2033')]: print('regime',a,b,stats(x[(x.date>=a)&(x.date<=b)]))
for h in [5,10,20,40]:
 z=x.copy(); z['fwd']=np.nan
 for s,d in px.items():
  if d is None: continue
  d=d.sort_values('date').set_index('date'); idx=d.index
  for dt in idx:
   if dt in z.date.values and idx.get_loc(dt)+h<len(d):
    z.loc[(z.symbol==s)&(z.date==dt),'fwd']=d.close.iloc[idx.get_loc(dt)+h]/d.close.loc[dt]-1
 z=z.dropna(); print('decay',h,stats(z)[0:4])
rank=x.pivot(index='date',columns='symbol',values='factor').rank(axis=1,pct=True)
print('turnover',rank.diff().abs().mean(axis=1).mean(),'coverage',x.symbol.nunique(), 'avg_n',x.groupby('date').size().mean())

