import numpy as np, pandas as pd
from alphacrafter.sim.utils import get_index_daily_data, get_stock_daily_data

U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
def fetch(s):
    d=get_index_daily_data(s, days=6000)
    if d is None or len(d)<150: d=get_stock_daily_data(s, days=6000)
    return d
px={}
for s in U:
 d=fetch(s)
 if d is not None:
  x=d.copy(); x['date']=pd.to_datetime(x['date']); x=x.sort_values('date').drop_duplicates('date').set_index('date')
  px[s]=x['close'].astype(float)
P=pd.DataFrame(px).sort_index(); r=P.pct_change()
# lagged, interpretable: risk-adjusted 20d momentum, only when slower 60d trend confirms
mom=P.pct_change(20); vol=r.rolling(20).std()*np.sqrt(252); slow=P.pct_change(60)
f=(mom/vol).where(slow>0).shift(1)
rows=[]
for h in [5,10,20,40]:
  fr=P.pct_change(h).shift(-h)
  vals=[]; dates=[]; counts=[]
  for dt in f.index:
   a=f.loc[dt]; b=fr.loc[dt]
   z=pd.concat([a,b],axis=1).dropna();
   if len(z)>=8:
    vals.append(z.iloc[:,0].corr(z.iloc[:,1],method='spearman')); dates.append(dt); counts.append(len(z))
  q=pd.Series(vals,index=dates).dropna(); ic=q.mean(); sd=q.std(ddof=1); ir=ic/sd*np.sqrt(252) if sd else np.nan
  print(f'{h}D dates={len(q)} avg_n={np.mean(counts):.3f} coverage={np.mean(counts)/15:.4f} IC={ic:.8f} ICIR={ir:.8f} hit={np.mean(q>0):.4f}')
# turnover and active coverage
rank=f.rank(axis=1,pct=True); turn=rank.diff().abs().mean(axis=1).mean()
print('overall_dates',len(f),'avg_valid',f.notna().sum(axis=1).mean(),'coverage',f.notna().sum().sum()/(len(f)*15),'turnover',turn)
# regimes for selected horizon
