import numpy as np,pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data,get_index_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
def load(s):
 d=get_stock_daily_data(s,5000)
 if d is None or len(d)<100: d=get_index_daily_data(s,5000)
 return None if d is None else d.set_index(pd.to_datetime(d.date)).close.astype(float)
P=pd.concat({s:load(s) for s in U if load(s) is not None},axis=1).sort_index(); r=P.pct_change()
# Calm relative momentum: lagged 30-session return divided by 30-session realized volatility,
# with a mild drawdown penalty, intended to favor persistent advances over noisy rallies.
ret=P.pct_change(30); vol=r.rolling(30,min_periods=20).std();
peak=P.rolling(60,min_periods=30).max(); dd=P/peak-1
raw=ret/(vol+1e-8) + 0.25*dd
f=raw.sub(raw.median(axis=1),axis=0).shift(1)
f.to_csv('scripts/miner_3_20350705_calm_relative_momentum_signal.csv',index_label='date')
for h in [5,10,20,40]:
