cs=ret20.sub(ret20.median(axis=1),axis=0)
disp=ret20.std(axis=1).rolling(20).mean()
scale=(disp/disp.rolling(120).median()).clip(.5,2.0)
sig=(-cs/(vol+1e-8)).mul(scale,axis=0)
